    c=call(e::Op::ClipEx,dc);c.object=region;c.flags=RGN_COPY;Check(!a.Call({},c).reply.status,"Owned region clipping");Check(!a.G(g::Op::Delete,region).reply.status,"Selected clip is a native copy");
