    c=call(e::Op::SetState,dc);c.flags=uint32_t(e::State::Graphics);c.args[0]=GM_ADVANCED;Check(a.Call({},c).graphics.value!=0,"Graphics mode native");
    XFORM transform{1,0,0,1,5,6};c=call(e::Op::World,dc);c.flags=1;std::memcpy(c.args,&transform,sizeof(transform));Check(a.Call({},c).graphics.value!=0,"Bounded transform accepted");c.args[0]=0x7FC00000;Check(a.Call({},c).reply.status==ERROR_INVALID_PARAMETER,"NaN transform refused");c.args[0]=0x41800000;Check(a.Call({},c).reply.status==ERROR_INVALID_PARAMETER,"Oversized transform refused");
    c=call(e::Op::World,dc);auto world=a.Call({},c);Check(!std::memcmp(world.graphics.pixels,&transform,sizeof(transform)),"Invalid transform leaves previous state intact");c.flags=2;c.mode=MWT_IDENTITY;a.Call({},c);
    c=call(e::Op::Path,dc);c.flags=1;Check(a.Call({},c).graphics.value!=0,"Path begun");bool exhausted=false;for(unsigned i=0;i<e::MaxPathPoints+2;++i){g::Command line;line.op=g::Op::Line;line.dc=dc;line.args[0]=int(i);line.args[1]=10;const auto result=a.Call({},line);if(result.reply.status){Check(result.reply.status==ERROR_NOT_ENOUGH_QUOTA,"Path points quota explicit");exhausted=true;break;}}Check(exhausted,"Path growth bounded before forwarding");c.flags=3;Check(a.Call({},c).graphics.value!=0,"Path abort after quota");
