HWND Root(DWORD pid){struct Search{DWORD pid;HWND hwnd=nullptr;}s{pid};EnumWindows([](HWND hwnd,LPARAM data)->BOOL{auto& x=*reinterpret_cast<Search*>(data);DWORD pid=0;GetWindowThreadProcessId(hwnd,&pid);wchar_t name[64]{};if(pid==x.pid){GetClassNameW(hwnd,name,64);if(!wcscmp(name,L"Aegis.ExpandedGdi.14.10E"))x.hwnd=hwnd;}return TRUE;},LPARAM(&s));return s.hwnd;}
COLORREF Capture(HWND hwnd){BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=16;info.bmiHeader.biHeight=-16;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* bits=nullptr;const auto bitmap=CreateDIBSection(nullptr,&info,0,&bits,nullptr,0);const auto dc=CreateCompatibleDC(nullptr);Check(bitmap&&dc,"Capture resources");const auto previous=SelectObject(dc,bitmap);Check(PrintWindow(hwnd,dc,PW_CLIENTONLY)!=FALSE,"Print native window");GdiFlush();const auto result=GetPixel(dc,5,5);SelectObject(dc,previous);DeleteDC(dc);DeleteObject(bitmap);return result;}


void GeometryBurst(const std::filesystem::path& helper){
    Client a(helper);const auto window=a.Window();Check(window!=0,"Geometry burst window");
    for(unsigned i=0;i<400;++i){u::Command c;c.op=u::Op::Position;c.window=window;const int x=100+int(i%200),y=100+int(i/200)*5,width=i%2?320:300;c.rect={x,y,x+width,y+200};c.flags=SWP_NOACTIVATE|SWP_NOZORDER;const auto reply=a.Call(c);Check(!reply.reply.status&&reply.reply.live[2]<=8,"Rapid native geometry must not exhaust the guest event queue");}
    const auto hwnd=Root(a.broker.ProcessForTesting());RECT bounds{},client{};Check(hwnd&&GetWindowRect(hwnd,&bounds)&&GetClientRect(hwnd,&client),"Final native geometry reference");const auto dpi=GetDpiForWindow(hwnd);Check(MulDiv(bounds.left,96,int(dpi))==299&&MulDiv(bounds.top,96,int(dpi))==105,"Native window retains final requested position");
    bool position=false,moved=false,sized=false;for(unsigned i=0;i<32;++i){u::Command poll;poll.op=u::Op::Poll;poll.flags=1;const auto reply=a.Call(poll).reply;if(!reply.value)break;if(reply.event.message==WM_WINDOWPOSCHANGED){position=true;Check(reply.event.rect.left==299&&reply.event.rect.top==105&&reply.event.rect.right==619&&reply.event.rect.bottom==305,"Latest typed WINDOWPOS is retained");}if(reply.event.message==WM_MOVE)moved=true;if(reply.event.message==WM_SIZE){sized=true;Check(LOWORD(reply.event.lp)==MulDiv(client.right,96,int(dpi))&&HIWORD(reply.event.lp)==MulDiv(client.bottom,96,int(dpi)),"Latest client dimensions reach the guest");}}
    Check(position&&moved&&sized,"Latest position, move and size notifications delivered");u::Command finish;finish.op=u::Op::Finish;finish.flags=1;Check(a.Call(finish).reply.completed,"Geometry burst cleanup");a.broker.Finish();
}

void ResizeDuringPaint(const std::filesystem::path& helper){
    Client a(helper);u::Command c;c.op=u::Op::Create;c.kind=u::Class::Custom;c.style=WS_OVERLAPPEDWINDOW|WS_VISIBLE;c.reserved=CS_HREDRAW|CS_VREDRAW;c.rect={100,100,500,400};
    const auto window=a.Call(c).reply.value;Check(window!=0,"Resize regression window");
    auto poll=[&](){u::Command q;q.op=u::Op::Poll;q.flags=1;return a.Call(q).reply;};
    bool firstPaint=false;for(unsigned i=0;i<100&&!firstPaint;++i){firstPaint=poll().event.message==WM_PAINT;if(!firstPaint)Sleep(5);}
    Check(firstPaint,"Initial guest paint delivered");
    // The guest has received WM_PAINT but has not reached BeginPaint. Force a
    // host resize and its native paint before the guest consumes that region.
    c={};c.op=u::Op::Position;c.window=window;c.rect={100,100,460,380};c.flags=SWP_NOACTIVATE|SWP_NOZORDER;Check(!a.Call(c).reply.status,"Resize during guest callback");
    c={};c.op=static_cast<u::Op>(d::Op::Redraw);c.window=window;c.flags=4;Check(!a.Call(c).reply.status,"Consume native resize paint while guest callback outstanding");
    const auto dc=a.G(g::Op::Paint,window).graphics.value;Check(dc!=0,"Old guest callback begins after resize");Check(!a.G(g::Op::EndPaint,dc).reply.status,"Old guest callback ends");
    bool size=false,repaint=false;for(unsigned i=0;i<100&&!repaint;++i){const auto event=poll().event;if(event.message==WM_SIZE)size=true;if(size&&event.message==WM_PAINT)repaint=true;if(!repaint)Sleep(5);}
    Check(size&&repaint,"Resize state reaches guest before a fresh paint");
    const auto fresh=a.G(g::Op::Paint,window).graphics.value;Check(fresh&&!a.G(g::Op::EndPaint,fresh).reply.status,"Fresh paint completes without a stale DC");
    c={};c.op=u::Op::Finish;c.flags=1;Check(a.Call(c).reply.completed,"Resize regression cleanup");a.broker.Finish();
}

